contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        require(address(this).balance >= value, "insufficient balance");

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        c.schedule(target, value, data, predecessor, salt, delay);

        uint256 tsBefore = c.getTimestamp(id);
        require(tsBefore > 0, "schedule did not record timestamp");

        uint256 minDelay = c.getMinDelay();
        require(tsBefore == block.timestamp + delay, "unexpected timestamp");
        require(delay >= minDelay, "delay below minimum");

        c.execute{value: value}(target, value, data, predecessor, salt);

        bool done = c.isOperationDone(id);
        require(done, "operation not marked done");
        require(c.getTimestamp(id) == 1, "timestamp not DONE");

        bool reverted;
        try c.updateDelay(minDelay + 1) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
    }

    receive() external payable {}
}

