contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay
    ) public payable {
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        c.grantRole(c.EXECUTOR_ROLE(), address(0));

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        c.schedule(target, value, data, predecessor, salt, delay);

        uint256 minDelay = c.getMinDelay();
        if (delay < minDelay) {
            bool scheduleReverted;
            try c.schedule(target, value, data, predecessor, salt, minDelay) {
                scheduleReverted = false;
            } catch {
                scheduleReverted = true;
            }
            assert(scheduleReverted);
        } else {
            bool reverted;
            try c.execute{value: msg.value}(target, value, data, predecessor, salt) {
                reverted = false;
            } catch {
                reverted = true;
            }
            bool done = c.isOperationDone(id);
            uint256 timestamp = c.getTimestamp(id);
            if (!reverted) {
                assert(done && timestamp == 1);
            } else {
                assert(!done || timestamp == 1);
            }
        }
    }
}

