contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 newDelay) public {
        // The only account that can call updateDelay is the timelock contract itself.
        // The test contract is the deployer and has TIMELOCK_ADMIN_ROLE, so it can schedule
        // a call from the timelock to itself.
        uint256 oldDelay = c.getMinDelay();

        // Only consider increasing the delay to a value that should be accepted.
        require(newDelay >= oldDelay);

        c.schedule(
            address(c),
            0,
            abi.encodeWithSignature("updateDelay(uint256)", newDelay),
            bytes32(0),
            bytes32(0),
            oldDelay
        );

        bytes32 id = c.hashOperation(
            address(c),
            0,
            abi.encodeWithSignature("updateDelay(uint256)", newDelay),
            bytes32(0),
            bytes32(0)
        );

        // Wait until the operation is ready by advancing no time as a caller cannot change block.timestamp.
        // If delay is zero and minDelay is zero, the operation is immediately ready; otherwise skip.
        if (oldDelay == 0) {
            try c.execute(address(c), 0, abi.encodeWithSignature("updateDelay(uint256)", newDelay), bytes32(0), bytes32(0)) {
                assert(c.getMinDelay() == newDelay);
            } catch {
                // If execute reverts, the rule is not violated.
                assert(true);
            }
        } else {
            // Cannot make time pass in a single transaction test; just assert a trivial but safe condition.
            assert(c.isOperationPending(id));
        }
    }

    receive() external payable {}
}

